const json = $input.first().json;
const firstKey = Object.keys(json)[0];

// destacando o objeto recebido da base
const data = JSON.parse(json[firstKey]);

// removendo propriedades nulas recursivamente
const cleaned = JSON.parse(JSON.stringify(data, (k, v) => v === null ? undefined : v));

return { json: cleaned };

const crypto = require('crypto');

// Pega os dados da validação
const user = $('Extrai a Credencial').first().json.data;
const data = $input.first().json.data;

const { username, password } = user;
const { senha_hash, payload } = data;

// Validação básica
if (!username || !password) {
  throw new Error('Credenciais não informadas');
}

if (!senha_hash) {
  throw new Error('Autenticação negada para este usuário');
}

// Gera hash da senha fornecida (usando SHA-256)
const hash = crypto.createHash('sha256').update(password).digest('hex');

// Compara com o hash salvo
if (hash !== senha_hash) {
  throw new Error('Senha incorreta');
}

// Monta o objeto de retorno com os dados necessários
return {
  code: 200,
  data: payload
};

const crypto = require('crypto');

const SECRET_KEY = $env["SECRET_KEY"] || 'your-secret-key-here';

const payload = $input.first().json.data;
const two_factor_enabled = !!payload.two_factor_enabled;

function base64urlEscape(str) {
  return str.replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

function generateJWT(payload, secret, expiresIn) {
  const header = {
    alg: 'HS256',
    typ: 'JWT'
  };

  payload.iat = Math.floor(Date.now() / 1000);
  payload.exp = payload.iat + expiresIn;

  const encodedHeader = base64urlEscape(
    Buffer.from(JSON.stringify(header)).toString('base64')
  );
  const encodedPayload = base64urlEscape(
    Buffer.from(JSON.stringify(payload)).toString('base64')
  );

  const signature = base64urlEscape(
    crypto
      .createHmac('sha256', secret)
      .update(encodedHeader + '.' + encodedPayload)
      .digest('base64')
  );

  return encodedHeader + '.' + encodedPayload + '.' + signature;
}

function generateRefreshToken() {
  return crypto.randomBytes(32).toString('hex');
}

function generateUUID() {
  return crypto.randomUUID();
}

// Gera access_token com 30 minutos de validade
//const access_token = generateJWT(payload, SECRET_KEY, 30 * 60);
const access_token = generateJWT(payload, SECRET_KEY, 24 * 60 * 60);

// Gera refresh_token
const refresh_token = generateRefreshToken();
const refresh_token_hash = crypto.createHash('sha256').update(refresh_token).digest('hex');

// Cria família de tokens para rotação
const familia_id = generateUUID();

// Define expiração do refresh_token (7 dias)
const expira_em = new Date();
expira_em.setDate(expira_em.getDate() + 7);

return {
  code: 200,
  data: {
    access_token,
    refresh_token,
    refresh_token_hash,
    familia_id,
    id_usuario: payload.id_usuario,
    expira_em: expira_em.toISOString(),
    token_type: "bearer",
    expires_in: 1800,
    requires_2fa: two_factor_enabled,
    payload
  }
};

const { error } = $input.first().json;
return {
  code: 500,
  message: error
};

const json = $input.first().json;
const { username, password } = (json.body || json);

if (!username) {
  return { code: 400, field: 'username', message: 'Usuário não informado' };
}
// Validação de email
if (!username.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/)) {
  return { code: 400, field: 'username', username: 'Email inválido' };
}
if (!password) {
  return { code: 400, field: 'password', message: 'Senha não informada' };
}

return {
  code: 200,
  data: {
    username: username.toLowerCase().trim(),
    password
  }
};

const json = $input.first().json;

// Se for resposta de sucesso com tokens, pegar dados do node "Gera os Tokens JWT"
if (json.code === 200 && json.data && json.data.access_token) {
  const {
    access_token,
    refresh_token,
    token_type,
    expires_in,
    requires_2fa,
    payload
  } = json.data;

  return {
    code: 200,
    data: { access_token, refresh_token, token_type, expires_in, requires_2fa, payload }
  };
}

// Para outros casos (erros, etc)
if (json.data) {
  return json;
} else {
  const { code, field, message, warnings, ...data } = json;
  return { 
    code, field, message, 
    data: Object.keys(data).length === 0 ? undefined : data, 
    warnings 
  };
}
